CREATE TABLE agreement_versions(tenant_id uuid REFERENCES tenants(id),id uuid NOT NULL,version integer NOT NULL,title text NOT NULL,body text NOT NULL,hash text NOT NULL,published_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,title,version));
CREATE TABLE agreement_events(tenant_id uuid,id uuid NOT NULL,subject_id uuid NOT NULL,version_id uuid NOT NULL,action text NOT NULL CHECK(action IN ('accepted','withdrawn')),producer text NOT NULL,idempotency_key text NOT NULL,received_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,producer,idempotency_key),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id),FOREIGN KEY(tenant_id,version_id) REFERENCES agreement_versions(tenant_id,id));
CREATE TABLE identity_links(tenant_id uuid,id uuid NOT NULL,member_id uuid NOT NULL,browser_id uuid NOT NULL,verified_by text NOT NULL,assertion_id text NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,assertion_id),FOREIGN KEY(tenant_id,member_id) REFERENCES subjects(tenant_id,id),FOREIGN KEY(tenant_id,browser_id) REFERENCES subjects(tenant_id,id));
CREATE TRIGGER agreement_version_immutable BEFORE UPDATE OR DELETE ON agreement_versions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER agreement_event_immutable BEFORE UPDATE OR DELETE ON agreement_events FOR EACH ROW EXECUTE FUNCTION immutable_record();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['agreement_versions','agreement_events','identity_links'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_boundary ON %I USING (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t); END LOOP; END $$;
